// Importing necessary modules and components
import React, { useState, useEffect } from 'react';
import axios from 'axios'; // Using axios instead of fetch
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import '../CSS/hero.css';

// Defining constants for the API key and base URL
const apiKey = '499d99db6ce23991d21afde0deede0f1';
const baseUrl = 'https://api.themoviedb.org/3';

// Defining a custom hook to use force update
const useForceUpdate = () => {
  const [value, setValue] = useState(0); // integer state
  return () => setValue(value => value + 1); // update the state to force render
}

// Defining the HeroSection component
function HeroSection() {
  // Setting up state for the list of movies, selected movie, and trailer video
  const [movies, setMovies] = useState([]);
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [trailerVideo, setTrailerVideo] = useState(null);
  const [isLoading, setIsLoading] = useState(false);

  // Using a custom hook to force update
  const forceUpdate = useForceUpdate();

  // Defining a function to play the trailer for a movie
  const playTrailer = async (movie) => {
    setIsLoading(true);
    setSelectedMovie(movie);

    // Fetching the videos for the selected movie from the TMDb API using axios
    const response = await axios.get(
      `${baseUrl}/movie/${movie.id}/videos`,
      {
        params: {
          api_key: apiKey,
        },
      }
    );

    // Finding the first video with type "Trailer"
    const trailer = response.data.results.find(
      (video) => video.type === 'Trailer' && video.site === 'YouTube'
    );

    // Setting the trailer video state
    setTrailerVideo(trailer);
    setIsLoading(false);
  };

  // Defining a function to close the trailer modal
  const closeTrailer = () => {
    setSelectedMovie(null);
    setTrailerVideo(null);
  };

  // Using an effect hook to fetch data from the API when the component mounts or the category changes
  useEffect(() => {
    const fetchData = async () => {
      let endpoint;
      switch (category) {
        case 'hollywood':
          endpoint = '/movie/popular';
          break;
        case 'bollywood':
          endpoint = '/discover/movie?with_original_language=hi';
          break;
        case 'lollywood':
          endpoint = '/discover/movie?with_original_language=ur';
          break;
        default:
          return;
      }

      // Fetching the popular movies from the TMDb API using axios
      const response = await axios.get(`${baseUrl}${endpoint}`, {
        params: {
          api_key: apiKey,
        },
      });
      setMovies(response.data.results);
    };
    fetchData();
  }, [category]);

  // Using an effect hook to force update the Slider component when the movie data changes
  useEffect(() => {
    forceUpdate();
  }, [movies]);

  // Defining settings for the Slider component
const settings = {
  dots: false,
  infinite: true,
  speed: 800,
  slidesToShow: 1,
  slidesToScroll: 1,
  autoplay: true,
  autoplaySpeed: 5000,
};
// Rendering the hero section with a slide show of movie posters and relevant information
return (
  <section className="hero-section">
    {movies && (
      <Slider {...settings}>
        {movies.map((movie) => (
          // Checking if the movie has a poster_path property and it is not null
          movie.poster_path && (
            <div className='hero-content' key={movie.id}>
              {/* Setting the movie poster as the background of the hero content */}
              <div className='hero-poster' style={{backgroundImage: `url(https://image.tmdb.org/t/p/w500${movie.poster_path})`}}></div>
              <div className="hero-info">
                <h1>{movie.title}</h1>
                <p>{movie.overview}</p>
                <div className="hero-details">
                  <span>{movie.vote_average} / 10</span>
                  <span>{movie.release_date}</span>
                  <span>
                    {movie.genres &&
                      movie.genres.map((genre) => genre.name).join(", ")}
                  </span>
                </div>
                <div className="hero-buttons">
                  <button>Play Now</button>
                  <button>Watch Trailer</button>
                </div>
              </div>
            </div>
          )
        ))}
      </Slider>
    )}
  </section>
);


}

// Exporting the HeroSection component as the default export
export default HeroSection;


